// Migrate applies every pending migration to the database behind pool, logging each
// one with how long it took, and returns how many it applied. Each migration runs in
// its own transaction, so one that fails leaves the database as it was before it, and
// a session lock keeps two servers starting at once from migrating together.
func Migrate(ctx context.Context, pool *pgxpool.Pool, log *slog.Logger) (int, error) {
	sqlDB := stdlib.OpenDBFromPool(pool)
	defer sqlDB.Close()
	locker, err := lock.NewPostgresSessionLocker()
	if err != nil {
		return 0, fmt.Errorf("migration lock: %w", err)
	}
	provider, err := goose.NewProvider(goose.DialectPostgres, sqlDB, Migrations, goose.WithSessionLocker(locker))
	if err != nil {
		return 0, fmt.Errorf("read migrations: %w", err)
	}
	results, err := provider.Up(ctx)
	for _, r := range results {
		log.Info("migration applied", "version", r.Source.Version, "file", r.Source.Path, "duration_ms", r.Duration.Milliseconds())
	}
	if err != nil {
		return len(results), fmt.Errorf("migrate: %w", err)
	}
	return len(results), nil
}

// NewPool connects to the database at url with a pool of connections, traced by
// tracer (nil for none), and checks it answers within 2 seconds, so a wrong
// DATABASE_URL stops the server at startup instead of failing the first request.
func NewPool(ctx context.Context, url string, tracer pgx.QueryTracer) (*pgxpool.Pool, error) {
	cfg, err := pgxpool.ParseConfig(url)
	if err != nil {
		return nil, fmt.Errorf("parse DATABASE_URL: %w", err)
	}
	cfg.ConnConfig.Tracer = tracer
	cfg.MaxConnIdleTime = 5 * time.Minute
	pool, err := pgxpool.NewWithConfig(ctx, cfg)
	if err != nil {
		return nil, fmt.Errorf("create pool: %w", err)
	}
	pingCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("connect to the database: %w", err)
	}
	return pool, nil
}

// mapError translates what pgx and PostgreSQL report into the domain's errors, so no
// layer above the store ever sees a pgx type:
//
//   - pgx.ErrNoRows becomes domain.ErrNotFound, as "task 999 not found";
//   - a unique violation (23505) becomes a *domain.ConflictError for its field;
//   - a foreign key (23503) or check (23514) violation becomes a
//     *domain.ValidationError for its field.
//
// Anything else is wrapped and stays a 500: an error nobody planned for should be
// seen in the logs and fixed, not dressed up as the client's fault.
func mapError(err error, entity string, id int64) error {
	if err == nil {
		return nil
	}
	if errors.Is(err, pgx.ErrNoRows) {
		if id == 0 {
			return fmt.Errorf("%s %w", entity, domain.ErrNotFound)
		}
		return fmt.Errorf("%s %d %w", entity, id, domain.ErrNotFound)
	}
	if pgErr, ok := errors.AsType[*pgconn.PgError](err); ok {
		rule, known := constraints[pgErr.ConstraintName]
		switch {
		case known && pgErr.Code == "23505":
			return domain.Conflict(rule.field, rule.message)
		case known && (pgErr.Code == "23503" || pgErr.Code == "23514"):
			return domain.Invalid(rule.field, rule.message)
		}
	}
	return fmt.Errorf("%s: %w", entity, err)
}

